#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/button_base/button_base.hpp"
#include "gui_forms/controls/button_base/check_box/check_box_capabilities/check_box_capabilities.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RadioButton's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/radio_button.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether the button is selected within its group (Checked); a view onto the check. Checking it clears the checked sibling of the same group_name first; a change raises checked_changed.
template <typename Declaring>
struct RadioButtonCheckedCapability {
    PropertyView<bool, RadioButtonCheckedCapability<Declaring>> checked;

    static void assign(RadioButtonCheckedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.checked), std::move(incoming));
    }

    static bool read(const RadioButtonCheckedCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.checked);
        return current;
    }
};

// The exclusion group among the parent's radio buttons (GroupName); empty is the parent's own group. A checked button that joins a group clears that group's checked sibling.
template <typename Declaring>
struct RadioButtonGroupNameCapability {
    PropertyCell<std::string, RadioButtonGroupNameCapability<Declaring>> group_name{};

    static void assign(RadioButtonGroupNameCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.group_name), incoming);
        if (!capability.group_name.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.group_name));
    }
};

// Whether activation checks the button (AutoCheck).
template <typename Declaring>
struct RadioButtonAutoCheckCapability {
    PropertyCell<bool, RadioButtonAutoCheckCapability<Declaring>> auto_check{true};

    static void assign(RadioButtonAutoCheckCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_check), incoming);
        if (!capability.auto_check.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_check));
    }
};

// How the choice mark draws: classic, modern or toggle (std::invalid_argument outside them).
template <typename Declaring>
struct RadioButtonIndicatorStyleCapability {
    PropertyCell<ChoiceIndicatorStyle, RadioButtonIndicatorStyleCapability<Declaring>> indicator_style{ChoiceIndicatorStyle::classic};

    static void assign(RadioButtonIndicatorStyleCapability& capability, ChoiceIndicatorStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indicator_style), incoming);
        if (!capability.indicator_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indicator_style));
    }
};

// Every RadioButton capability, in the order the declaring class takes them.
template <typename Declaring>
struct RadioButtonCapabilities : public RadioButtonCheckedCapability<Declaring>,
                                 public RadioButtonGroupNameCapability<Declaring>,
                                 public RadioButtonAutoCheckCapability<Declaring>,
                                 public RadioButtonIndicatorStyleCapability<Declaring> {};

} // namespace gui_forms
